"""evt -- fingerprint for discrete state sequences via transition timing, DETECTOR ONLY.

Detect (blind): for every transition observed at tick resolution, a keyed bit says which parity its tick should have.
T = (2 * #matches - N) / sqrt(N); under H0 the matches are Binomial(N, 1/2) exactly.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..addressing import AddressSpec, compute_address
from ..prf import domain_id, prf_sign
from ._stats import z_to_p


NAME = "evt"


BUCKET = 64


def _codes(s: pd.Series) -> np.ndarray:
    """Content-based stable integer code per state value (independent of order of appearance)."""
    import hashlib
    u = pd.unique(s.astype(str))
    m = {v: int.from_bytes(hashlib.blake2b(v.encode(), digest_size=4).digest(), "little") for v in u}
    return s.astype(str).map(m).to_numpy(np.int64)


def _bits(key, col, frm, to, tick):
    idx = (frm * 1_000_003 + to) * 1_000_033 + (tick // BUCKET)
    return prf_sign(key, domain_id("evt:" + col), idx.astype(np.int64)) > 0


def detect(df: pd.DataFrame, key: bytes, addr: AddressSpec, columns: list[str], **_):
    per, zs, ns = {}, [], []
    ad = compute_address(df, addr)
    order = np.argsort(ad, kind="stable")
    for c in columns:
        if c not in df.columns:
            per[c] = {"missing": True}
            continue
        code = _codes(df[c])[order]
        tick = ad[order]
        tr = np.flatnonzero(code[1:] != code[:-1]) + 1
        tr = tr[np.abs(tick[tr] - tick[tr - 1]) == 1]          # only transitions observed at tick resolution
        if tr.size < 10:
            per[c] = {"skipped": True, "transitions": int(tr.size)}
            continue
        match = ((tick[tr] & 1) == 1) == _bits(key, c, code[tr - 1], code[tr], tick[tr])
        N = int(tr.size)
        z = float((2 * match.sum() - N) / np.sqrt(N))
        per[c] = {"z": z, "n": N, "match_rate": float(match.mean()), "p": z_to_p(z), "tests": 1}
        zs.append(z); ns.append(N)
    if not zs:
        return {"method": NAME, "columns": per, "z": 0.0, "p": 1.0}
    z = float(np.sum(np.sqrt(ns) * np.array(zs)) / np.sqrt(np.sum(ns)))   # pooled binomial
    return {"method": NAME, "columns": per, "z": z, "p": z_to_p(z)}
